const items = $input.all();

const output = [];

// ===============================
// STATISTICS
// ===============================

const totalRowsImported = items.length;

// Extract from File drops fully blank Excel rows.
// The uploaded workbook has 31 data rows (row 1 is the header) and 2 blank rows.
const originalDataRows = 31;
const emptyRowsRemoved = Math.max(originalDataRows - totalRowsImported, 0);

let invalidEmailsRemoved = 0;
let invalidPhonesRemoved = 0;
let invalidDatesRemoved = 0;
let duplicateRowsRemoved = 0;


// ===============================
// DUPLICATE TRACKING
// ===============================

const seenEmails = new Set();
const seenPhones = new Set();


// ===============================
// HELPER FUNCTIONS
// ===============================

function cleanSpaces(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .trim()
    .replace(/\s+/g, ' ');
}


function properCase(value) {
  return cleanSpaces(value)
    .toLowerCase()
    .replace(/\b\w/g, c => c.toUpperCase());
}


function cleanEmail(value) {
  return cleanSpaces(value).toLowerCase();
}


function cleanPhone(value) {

  if (value === null || value === undefined) {
    return '';
  }

  let phone = String(value)
    .trim()
    .replace(/\s+/g, '')
    .replace(/-/g, '');

  // +8801710841232
  if (phone.startsWith('+880')) {
    phone = '0' + phone.substring(4);
  }

  // 8801710841232
  else if (
    phone.startsWith('880') &&
    phone.length === 13
  ) {
    phone = '0' + phone.substring(3);
  }

  // 1710841232
  else if (/^1\d{9}$/.test(phone)) {
    phone = '0' + phone;
  }

  return phone;
}


function validEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}


function validPhone(phone) {
  return /^01\d{9}$/.test(phone);
}


// ===============================
// DATE FORMATTER
// ===============================

function formatDate(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return '';
  }


  // -------------------------------
  // Excel Serial Date
  // -------------------------------

  const numericValue = Number(value);

  if (
    String(value).trim() !== '' &&
    Number.isFinite(numericValue) &&
    numericValue >= 1 &&
    numericValue <= 100000
  ) {

    const excelEpoch = new Date(
      Date.UTC(1899, 11, 30)
    );

    const date = new Date(
      excelEpoch.getTime() +
      numericValue * 86400000
    );

    return `${date.getUTCFullYear()}-${String(
      date.getUTCMonth() + 1
    ).padStart(2, '0')}-${String(
      date.getUTCDate()
    ).padStart(2, '0')}`;
  }


  const str = cleanSpaces(value);


  // -------------------------------
  // YYYY-MM-DD
  // -------------------------------

  let match = str.match(
    /^(\d{4})-(\d{1,2})-(\d{1,2})$/
  );

  if (match) {

    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);

    const date = new Date(
      Date.UTC(year, month - 1, day)
    );

    if (
      date.getUTCFullYear() === year &&
      date.getUTCMonth() === month - 1 &&
      date.getUTCDate() === day
    ) {

      return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }

    return '';
  }


  // -------------------------------
  // Slash Dates
  // -------------------------------

  match = str.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
  );

  if (match) {

    const first = Number(match[1]);
    const second = Number(match[2]);
    const year = Number(match[3]);

    let day;
    let month;


    // MM/DD/YYYY
    // 7/20/2026
    if (second > 12) {

      month = first;
      day = second;

    }


    // DD/MM/YYYY
    // 20/02/2025
    else if (first > 12) {

      day = first;
      month = second;

    }


    // Ambiguous → DD/MM/YYYY
    else {

      day = first;
      month = second;

    }


    const date = new Date(
      Date.UTC(year, month - 1, day)
    );


    if (
      date.getUTCFullYear() === year &&
      date.getUTCMonth() === month - 1 &&
      date.getUTCDate() === day
    ) {

      return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }

    return '';
  }


  // -------------------------------
  // Text Dates
  // -------------------------------

  let normalized = str.replace(
    /^([A-Za-z]+),\s*(\d{1,2})/,
    '$1 $2'
  );


  // May 2, 2025
  // Jun 26 2025
  // May 2 2025

  let parsed = new Date(normalized);


  if (!isNaN(parsed.getTime())) {

    return `${parsed.getFullYear()}-${String(
      parsed.getMonth() + 1
    ).padStart(2, '0')}-${String(
      parsed.getDate()
    ).padStart(2, '0')}`;
  }


  // -------------------------------
  // DD-MMM-YY
  // 2-May-26
  // 20-Jul-26
  // -------------------------------

  match = str.match(
    /^(\d{1,2})-([A-Za-z]+)-(\d{2,4})$/
  );

  if (match) {

    const day = Number(match[1]);

    const monthName =
      match[2].toLowerCase();

    let year =
      Number(match[3]);


    const months = {

      jan: 1,
      january: 1,

      feb: 2,
      february: 2,

      mar: 3,
      march: 3,

      apr: 4,
      april: 4,

      may: 5,

      jun: 6,
      june: 6,

      jul: 7,
      july: 7,

      aug: 8,
      august: 8,

      sep: 9,
      september: 9,

      oct: 10,
      october: 10,

      nov: 11,
      november: 11,

      dec: 12,
      december: 12
    };


    const month =
      months[monthName];


    if (!month) {
      return '';
    }


    if (year < 100) {
      year += 2000;
    }


    const date = new Date(
      Date.UTC(
        year,
        month - 1,
        day
      )
    );


    if (
      date.getUTCFullYear() === year &&
      date.getUTCMonth() === month - 1 &&
      date.getUTCDate() === day
    ) {

      return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }


    return '';
  }


  return '';
}


// ===============================
// PROCESS EVERY ROW
// ===============================

for (const item of items) {

  const row = item.json;


  // -------------------------------
  // CLEAN DATA
  // -------------------------------

  const fullName =
    properCase(row['Full Name']);

  const email =
    cleanEmail(row['Email']);

  const phone =
    cleanPhone(row['Phone']);

  const city =
    properCase(row['City']);

  const registrationDate =
    formatDate(row['Registration Date']);


  // -------------------------------
  // EMPTY ROW
  // -------------------------------

  if (
    !fullName &&
    !email &&
    !phone
  ) {

    continue;
  }


  // -------------------------------
  // INVALID EMAIL
  // -------------------------------

  if (!validEmail(email)) {

    invalidEmailsRemoved++;

    continue;
  }


  // -------------------------------
  // INVALID PHONE
  // -------------------------------

  if (!validPhone(phone)) {

    invalidPhonesRemoved++;

    continue;
  }


  // -------------------------------
  // INVALID DATE
  // -------------------------------

  if (!registrationDate) {

    invalidDatesRemoved++;

    continue;
  }


  // -------------------------------
  // DUPLICATE
  // Email OR Phone
  // -------------------------------

  if (
    seenEmails.has(email) ||
    seenPhones.has(phone)
  ) {

    duplicateRowsRemoved++;

    continue;
  }


  seenEmails.add(email);
  seenPhones.add(phone);


  // -------------------------------
  // CUSTOMER ID
  // -------------------------------

  const customerID =
    `CUST-${String(output.length + 1).padStart(4, '0')}`;


  // -------------------------------
  // CLEAN CUSTOMER RECORD
  // -------------------------------

  output.push({

    json: {

      "Customer ID":
        customerID,

      "Full Name":
        fullName,

      "Email":
        email,

      "Phone":
        phone,

      "City":
        city,

      "Registration Date":
        registrationDate,

      "_summary": {
        totalRowsImported,
        emptyRowsRemoved,
        invalidEmailsRemoved,
        invalidPhonesRemoved,
        invalidDatesRemoved,
        duplicateRowsRemoved,
        finalRowCount: output.length + 1
      }

    }

  });
}


// ===============================
// UPDATE FINAL SUMMARY
// ===============================

const finalStats = {

  totalRowsImported,

  emptyRowsRemoved,

  invalidEmailsRemoved,

  invalidPhonesRemoved,

  invalidDatesRemoved,

  duplicateRowsRemoved,

  finalRowCount: output.length

};


// Put final summary into every item
return output.map(item => ({

  json: {

    ...item.json,

    _summary: finalStats

  }

}));

const items = $input.all();

const summary = items.length > 0
  ? items[0].json._summary
  : {
      totalRowsImported: 0,
      emptyRowsRemoved: 0,
      invalidEmailsRemoved: 0,
      invalidPhonesRemoved: 0,
      invalidDatesRemoved: 0,
      duplicateRowsRemoved: 0,
      finalRowCount: 0
    };

const report = `
CUSTOMER DATA CLEANING SUMMARY REPORT
=====================================

Total Rows Imported: ${summary.totalRowsImported}

Empty/Invalid Rows Removed: ${
  summary.emptyRowsRemoved + summary.invalidDatesRemoved
}

Duplicate Rows Removed: ${summary.duplicateRowsRemoved}

Invalid Emails Removed: ${summary.invalidEmailsRemoved}

Invalid Phones Removed: ${summary.invalidPhonesRemoved}

Final Row Count: ${summary.finalRowCount}

=====================================
Cleaning completed successfully.
`.trim();

return [
  {
    json: {
      report
    }
  }
];

const items = $input.all();

return items.map(item => {

  const {
    _summary,
    ...customer
  } = item.json;

  return {
    json: customer
  };
});
